
/* Menu-only assets: independent of the Campaign/Arcade screen titles. */
#menu.bp-menu-ready #bpArcadeHome #bpCampaignOpen,
#menu.bp-menu-ready #bpArcadeHome #bpArcadeOpen{position:relative!important;padding-left:clamp(88px,24%,128px)!important;overflow:visible!important;isolation:isolate}
#menu.bp-menu-ready #bpArcadeHome #bpCampaignOpen::before,
#menu.bp-menu-ready #bpArcadeHome #bpArcadeOpen::before{content:"";position:absolute;left:10px;top:50%;transform:translateY(-50%);width:clamp(72px,22%,112px);height:calc(100% - 12px);background-repeat:no-repeat;background-size:contain;background-position:center;pointer-events:none}
#menu.bp-menu-ready #bpArcadeHome #bpCampaignOpen::before{background-image:url("data:image/png;base64,")}
#menu.bp-menu-ready #bpArcadeHome #bpArcadeOpen::before{background-image:url("data:image/png;base64,")}
#menu.bp-menu-ready #bpArcadeHome #bpCampaignOpen .bp-feature-title,
#menu.bp-menu-ready #bpArcadeHome #bpArcadeOpen .bp-arcade-title{font-size:clamp(17px,4.5vw,26px)!important;gap:6px}
#menu.bp-menu-ready #bpArcadeHome #bpCampaignOpen .bp-feature-title>span,
#menu.bp-menu-ready #bpArcadeHome #bpArcadeOpen .bp-arcade-title>span{white-space:nowrap;font-size:clamp(11px,2.6vw,15px)}
@media(max-width:390px){#menu.bp-menu-ready #bpArcadeHome #bpCampaignOpen,#menu.bp-menu-ready #bpArcadeHome #bpArcadeOpen{padding-left:85px!important;padding-right:10px!important}}
